/* Service worker for Test. Generated by Entity Tracker. */

// A fetch handler has to exist for the install prompt to be offered. It
// deliberately does nothing: a cache nobody asked for is how a site starts
// serving last week's pages.
self.addEventListener("fetch", () => {});

self.addEventListener("push", (event) => {
  const said = (() => {
    try { return event.data ? event.data.json() : {}; }
    catch { return { body: event.data ? event.data.text() : "" }; }
  })();

  event.waitUntil(self.registration.showNotification(said.title || "Test", {
    body: said.body || "",
    icon: said.icon || "icons/icon-192.png",
    badge: "icons/icon-192.png",
    data: { url: said.url || "/" },
  }));
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const go = (event.notification.data && event.notification.data.url) || "/";
  event.waitUntil(clients.matchAll({ type: "window", includeUncontrolled: true }).then((open) => {
    // A tab that is already on this site is focused rather than a second
    // one being opened beside it.
    for (const tab of open) if ("focus" in tab) return tab.focus();
    return clients.openWindow(go);
  }));
});
